        </div>

        <div className="form-group">
          <label className="form-label" htmlFor="metalness-slider">
            <span>金属感 (Metalness)</span>
          </label>
          <div className="slider-row">
            <input
              id="metalness-slider"
              type="range"
              min="0"
              max="1"
              step="0.05"
              className="slider-input"
              value={config.metalness}
              onChange={(e) => updateConfig('metalness', parseFloat(e.target.value))}
            />
            <span className="slider-value">{Math.round(config.metalness * 100)}%</span>
          </div>
        </div>

        {/* 表示モード切り替え */}
