              <Layers size={15} />
              エッジ線
            </button>
            <button
              type="button"
              className={`toggle-btn ${config.wireframe ? 'toggle-btn-active' : ''}`}
              aria-pressed={config.wireframe}
              onClick={() => updateConfig('wireframe', !config.wireframe)}
            >
              <Box size={15} />
              ワイヤー
            </button>
          </div>
        </div>

        {/* モーション制御 */}
        <div className="section-title">モーション制御</div>
        <div className="form-group">
          <label className="form-label">自動回転</label>
          <div className="toggle-row">
            <button
              type="button"
              className={`toggle-btn ${config.autoRotate ? 'toggle-btn-active' : ''}`}
              aria-pressed={config.autoRotate}
              onClick={() => updateConfig('autoRotate', !config.autoRotate)}
            >
              <RotateCw size={15} />
              {config.autoRotate ? '自動回転中' : '停止中'}
            </button>
          </div>
        </div>

        <div className="form-group">
          <label className="form-label" htmlFor="speed-slider">
            <span>回転速度</span>
          </label>
          <div className="slider-row">
            <input
              id="speed-slider"
              type="range"
              min="0.2"
              max="3.0"
              step="0.1"
              className="slider-input"
              value={config.rotateSpeed}
              disabled={!config.autoRotate}
              style={{ opacity: config.autoRotate ? 1 : 0.4 }}
              onChange={(e) => updateConfig('rotateSpeed', parseFloat(e.target.value))}
            />
            <span className="slider-value">{config.rotateSpeed.toFixed(1)}x</span>
          </div>
        </div>

        {/* リセットボタン */}
        <button
          type="button"
          className="btn-reset"
          onClick={onReset}
        >
          <RotateCcw size={16} />
          初期状態にリセット
        </button>
      </div>
    </div>
  );
}

import { useState, useCallback, useEffect } from 'react';
import CubeCanvas from './components/CubeCanvas';
import ControlsPanel from './components/ControlsPanel';
import { CubeConfig, DEFAULT_CUBE_CONFIG } from './types';
import './index.css';

export default function App() {
  const [config, setConfig] = useState<CubeConfig>(DEFAULT_CUBE_CONFIG);
  const [resetSignal, setResetSignal] = useState<number>(0);

  const handleReset = useCallback(() => {
    setConfig(DEFAULT_CUBE_CONFIG);
    setResetSignal((prevTimestamp) => Date.now());
  }, []);

  const handleChange = useCallback((newConfig: CubeConfig) => {
    setConfig(newConfig);
  }, []);

  // キーボードショートカット: スペースキーで回転トグル、Rキーでリセット
  useEffect(() => {
    const handleKeyDown = (event: KeyboardEvent) => {
      // フォーム入力中のショートカット発火を防止
      const activeElement = document.activeElement;
      if (
        activeElement &&
        (activeElement.tagName === 'INPUT' ||
          activeElement.tagName === 'TEXTAREA' ||
          activeElement.tagName === 'SELECT')
      ) {
        return;
      }

      if (event.code === 'Space') {
        event.preventDefault();
        setConfig((prev) => ({
          ...prev,
          autoRotate: !prev.autoRotate,
        }));
      } else if (event.key === 'r' || event.key === 'R') {
        event.preventDefault();
        handleReset();
      }
    };

    window.addEventListener('keydown', handleKeyDown);
    return () => {
      window.removeEventListener('keydown', handleKeyDown);
    };
  }, [handleReset]);

  return (
    <div className="app-container">
      <header className="header" role="banner">
        <h1 className="title">インタラクティブ 3Dキューブ</h1>
        <p className="subtitle">
          Three.jsで描画された立方体を直感的にドラッグ回転・ズーム操作
        </p>
      </header>

      <main className="main-layout" role="main">
        <section aria-label="3Dビュー" style={{ display: 'contents' }}>
          <CubeCanvas config={config} resetSignal={resetSignal} />
        </section>
        <section aria-label="操作パネル" style={{ display: 'contents' }}>
          <ControlsPanel
            config={config}
            onChange={handleChange}
            onReset={handleReset}
          />
        </section>
      </main>
    </div>
  );
}
